        n = x.shape[0]
        h = x.shape[2]
        w = x.shape[3]
        oh = h - 2
        ow = w - 2
        out = torch.empty((n, 32, oh, ow), dtype=torch.bfloat16, device=x.device)
        if n == 0 or oh <= 0 or ow <= 0:
            return out

        module = _get_ptx_module()
        module = _get_ptx_module()
        tiles_x = (ow + 7) // 8
        tiles_y = (oh + 7) // 8
        module.launch(
            "conv3x3_bf16",
            grid=(tiles_x * tiles_y, n, 1),
            block=(128, 1, 1),
            arguments=[x, weight, out, i32(h), i32(w), i32(oh), i32(ow)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
